DELETE FROM AUD_PIPELINES_RUN_LOG WHERE PIPELINE_RUN_ID IN (
SELECT t.PIPELINE_RUN_ID AS row_id FROM AUD_PIPELINES_RUN_LOG t WHERE (EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND r.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND r.END_DATE < :cutoff AND r.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)) AND (t.TRIGGER_KIND<>'SCHEDULE' OR EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG newer WHERE newer.PIPELINE_ID=t.PIPELINE_ID AND newer.TRIGGER_KIND='SCHEDULE' AND newer.PIPELINE_RUN_ID>t.PIPELINE_RUN_ID))
AND NOT EXISTS (SELECT 1 FROM AUD_ACTIONS incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_CONTROL_REQUESTS incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_DEPENDENCY_CONSUMPTION incoming WHERE incoming.CONSUMED_PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_DEPENDENCY_CONSUMPTION incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_GATE_DECISIONS incoming WHERE incoming.SELECTED_PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_GATE_DECISIONS incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_GATE_WAITS incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_RUN_INTERVENTIONS incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_TASK_RUN_LOG incoming WHERE incoming.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)
ORDER BY t.PIPELINE_RUN_ID LIMIT 10000
)
